import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.CdvW4CUT.js";const b=JSON.parse('{"title":"终端 UI","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tui.md","filePath":"guide/tui.md","lastUpdated":1793803670000}'),r={name:"guide/tui.md"};function c(l,t,i,h,n,s){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="终端-ui" tabindex="-1">终端 UI <a class="header-anchor" href="#终端-ui" aria-label="Permalink to &quot;终端 UI&quot;">​</a></h1><p>终端 UI 用 bubbletea + lipgloss 实现，视觉规范按实际落地：顶部圆角标题条、左侧蓝色竖条的用户块、等宽工具行、底部带左边条的输入框。</p><h2 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按键</th><th>作用</th></tr></thead><tbody><tr><td><code>Enter</code></td><td>发送（Shift+Enter 换行）</td></tr><tr><td><code>Esc</code></td><td>运行中停止当前轮 / 关闭浮层</td></tr><tr><td><code>Ctrl+C</code></td><td>退出</td></tr><tr><td><code>Ctrl+P</code></td><td>打开会话列表（↑/↓、j/k 选择，Enter 打开，d 删除）</td></tr><tr><td><code>Ctrl+E</code></td><td>把当前会话导出为 Markdown 文件</td></tr><tr><td><code>a</code> / <code>A</code> / <code>d</code></td><td>权限确认浮层中：允许 / 总是允许 / 拒绝</td></tr></tbody></table><h2 id="斜杠命令" tabindex="-1">斜杠命令 <a class="header-anchor" href="#斜杠命令" aria-label="Permalink to &quot;斜杠命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/help</code></td><td>显示帮助浮层</td></tr><tr><td><code>/sessions</code></td><td>打开会话列表（等同 Ctrl+P）</td></tr><tr><td><code>/readonly</code></td><td>在「只读浏览」与「可编辑继续」之间切换</td></tr><tr><td><code>/export</code></td><td>导出当前会话为 Markdown（等同 Ctrl+E）</td></tr><tr><td><code>/new</code></td><td>开新会话</td></tr><tr><td><code>/clear</code></td><td>清空当前会话</td></tr></tbody></table><h2 id="交互式权限" tabindex="-1">交互式权限 <a class="header-anchor" href="#交互式权限" aria-label="Permalink to &quot;交互式权限&quot;">​</a></h2><p>标准档位下，<code>bash</code> / <code>write</code> / <code>edit</code> / <code>make_dir</code> / <code>move</code> / <code>copy</code> / <code>delete</code> 等高风险工具执行前会弹出确认浮层：</p><ul><li><code>a</code> 本次允许</li><li><code>A</code> 总是允许（计入本进程白名单，直到退出）</li><li><code>d</code> 或 <code>Esc</code> 拒绝</li></ul><p>只读档位由全局 guard 直接拦截写工具，完全档位跳过确认。</p><h2 id="只读浏览模式" tabindex="-1">只读浏览模式 <a class="header-anchor" href="#只读浏览模式" aria-label="Permalink to &quot;只读浏览模式&quot;">​</a></h2><p>用 <code>-view &lt;id&gt;</code> 或会话内 <code>/readonly</code> 进入只读浏览：可滚动查看历史、可用 Ctrl+P 切换会话，但禁止发送新消息、隐藏输入框。适合复盘或演示。</p>',12)])])}const p=d(r,[["render",c]]);export{b as __pageData,p as default};
